const {JSDOM}=require('jsdom');const fs=require('fs');const assert=require('node:assert/strict');
for(const file of ['ha-vacuum-water-monitor.js','custom_components/ha_vacuum_water_monitor/www/ha-vacuum-water-monitor.js'])for(const lang of ['pl','en']){
 const dom=new JSDOM('<body></body>',{runScripts:'dangerously',url:'http://localhost/'});dom.window.eval(fs.readFileSync(file,'utf8'));const c=dom.window.document.createElement('ha-vacuum-water-monitor');c.setConfig({devices:[]});c._lang=lang;
 const device={vacuum_entity:'vacuum.demo'};
 const data={initialized:true,remainingL:2,totalMl:4000,profileKey:'demo',uncertaintyPercent:20,calibrationHistory:[{ts:1,error_percent:-12.3,accepted:true},{ts:2,error_percent:0,accepted:false,reason:'incomplete_exposure'},{ts:3,error_percent:8,accepted:true},{ts:4,error_percent:-4,accepted:true},{ts:5,error_percent:null,accepted:false,reason:'insufficient_exposure'},{ts:6,error_percent:40,accepted:true}]};
 c._health={'vacuum.demo':{initialized:true,uncertainty_percent:20,supply:{basis_runs:3,cleanings_left:5,days_left:10},typical_error_percent:8}};
 const root=dom.window.document.createElement('div');root.innerHTML=c._buildSupplyAnswer(device,data);assert.match(root.querySelector('[data-water-range]').textContent,/1[.,]60.*2[.,]40/);assert.match(root.querySelector('[data-cleanings-range]').textContent,/4.*6/);assert.match(root.querySelector('[data-days-range]').textContent,/8.*12/);
 root.innerHTML=c._buildSupplyAnswer(device,{...data,remainingL:null});assert.equal(root.querySelector('[data-cleanings-range]'),null);
 root.innerHTML=c._buildSupplyAnswer(device,{...data,profileKey:null});assert.equal(root.querySelector('[data-cleanings-range]'),null);
 c._health['vacuum.demo'].supply={basis_runs:2,cleanings_left:null,days_left:null};root.innerHTML=c._buildSupplyAnswer(device,data);assert.match(root.querySelector('[data-learning]').textContent,/2.*3/);assert.equal(root.querySelector('[data-days-range]'),null);
 root.innerHTML=c._buildEstimateConfidence(device,data);assert.equal(root.querySelectorAll('[data-tank-error]').length,5);assert.equal(root.querySelector('[data-tank-error]').textContent,'-12.3%');assert.ok(root.querySelector('[data-typical-error]'));assert.ok(root.querySelector('[data-confidence-caption]'));assert.equal(root.querySelectorAll('[data-confidence-view]').length,2);
 root.innerHTML=c._buildEstimateConfidence(device,{...data,calibrationHistory:data.calibrationHistory.slice(0,3)});assert.equal(root.querySelector('[data-typical-error]'),null);
 const diagnostics=dom.window.document.createElement('div');diagnostics.innerHTML=c._buildDiagnostics(data);const label=[...diagnostics.querySelectorAll('.diagnostics-label')].find(el=>el.textContent===c._waterText('Last empty tanks'));assert.equal(label.nextElementSibling.textContent,data.calibrationHistory.slice(0,5).map(t=>c._tankErrorText(t)).join(', '));dom.window.close();
}console.log('V3 range/gates and V4 exact five-tank evidence PASS');
